def test_hyb_gga_xc_cam_o3lyp_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_cam_o3lyp", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-8.353631492107329e+00, -8.179763440300169e+00, -7.935501968751351e+00, -7.595954022759839e+00, -7.131137128448693e+00, -6.508856847932703e+00, -5.702239470465285e+00, -4.704431345701291e+00, -3.551787792164340e+00, -2.356032341491051e+00, -1.365856592173418e+00, -9.399657198304214e-01, -7.772132013263706e-01, -5.572495357439486e-01, -2.864959106623404e-01, -8.309290726054049e-02, -7.830665827954088e-03, -2.509387887090606e-03, -4.960410884118871e-04, -6.223800201958111e-05]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


